mapper.update:
UPDATE PEACH_ORGANIZATION
SET ORG_NAME = #{orgName}, VERSION = VERSION + 1,
    MODIFY_TIME = DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
    MODIFIER_ID = #{operatorRefId}
WHERE ID = #{id} AND TENANT_ID = #{tenantBusinessId}
  AND VERSION = #{version} AND STATUS = 'ENABLE' AND IS_DELETE = 0

mapper.select:
SELECT
    (SELECT COUNT(1) FROM PEACH_ORGANIZATION
     WHERE TENANT_ID = #{tenantBusinessId}
       AND PARENT_ORG_REF_ID = #{orgRefId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_USER_ORG
       WHERE TENANT_ID = #{tenantBusinessId}
         AND ORG_ID = #{orgId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_USER
       WHERE TENANT_ID = #{tenantBusinessId}
         AND DEFAULT_ORG_ID = #{orgId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_ROLE
       WHERE TENANT_ID = #{tenantBusinessId}
         AND ORG_ID = #{orgId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_MEMBER_ROLE_BINDING
       WHERE TENANT_REF_ID = #{tenantRefId}
         AND SCOPE_REF_ID = #{orgRefId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_ROLE_DATA_POLICY
       WHERE TENANT_REF_ID = #{tenantRefId}
         AND ORG_REF_ID = #{orgRefId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_AUTH_PARTY
       WHERE TENANT_ID = #{tenantBusinessId}
         AND ORG_ID = #{orgId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_AUTH_FUNCTION
       WHERE TENANT_ID = #{tenantBusinessId}
         AND ORG_ID = #{orgId} AND IS_DELETE = 0)
    + (SELECT COUNT(1) FROM PEACH_AUTH_RESOURCE
       WHERE TENANT_ID = #{tenantBusinessId}
         AND ORG_ID = #{orgId} AND IS_DELETE = 0)
